css:
.sfs-sim{--sfs-ink:#1f2a33;--sfs-soft:#46535e;--sfs-cream:#fffaf1;--sfs-line:#e6dccb;--sfs-pink:#b5481a;--sfs-violet:#0e6b6b;--sfs-green:#2f7d3f;--sfs-red:#b8302a;--sfs-gold:#f2b134;--sfs-night:#14424a;
 font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:var(--sfs-ink);background:var(--sfs-cream);
 background-image:radial-gradient(rgba(14,107,107,.08) 1.5px,transparent 1.5px);background-size:16px 16px;
 border-radius:18px;padding:18px;max-width:1160px;margin:0 auto;box-sizing:border-box;overflow-x:hidden;}
.sfs-sim *{box-sizing:border-box;}
.sfs-sim .sfs-header{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px;}
.sfs-sim .sfs-title{display:flex;align-items:center;gap:12px;min-width:0;}
.sfs-sim .sfs-logo{font-size:34px;line-height:1;background:var(--sfs-night);border:3px solid var(--sfs-gold);border-radius:50%;width:58px;height:58px;flex:0 0 58px;display:flex;align-items:center;justify-content:center;box-shadow:0 3px 0 rgba(20,66,74,.25);}
.sfs-sim .sfs-title h1{font-size:1.55rem;margin:0;font-weight:800;letter-spacing:-.01em;color:var(--sfs-violet);}
.sfs-sim .sfs-title p{margin:2px 0 0;font-size:.92rem;color:var(--sfs-soft);}
.sfs-sim .sfs-stats{display:flex;gap:8px;flex-wrap:wrap;}
.sfs-sim .sfs-chip{background:#fff;border:1px solid var(--sfs-line);border-radius:999px;padding:6px 12px;font-size:.88rem;color:var(--sfs-ink);white-space:nowrap;}
.sfs-sim .sfs-chip b{font-size:1.02rem;}
.sfs-sim .sfs-hero{border-width:2px;font-weight:600;border-color:var(--sfs-green);background:#eaf6ec;}
.sfs-sim .sfs-hero.sfs-neg{border-color:var(--sfs-red);background:#fdeceb;}
.sfs-sim .sfs-grid{display:grid;grid-template-columns:360px 1fr;gap:14px;align-items:start;}
.sfs-sim .sfs-main{display:flex;flex-direction:column;gap:14px;min-width:0;}
.sfs-sim .sfs-card{background:#fff;border:1px solid var(--sfs-line);border-radius:14px;padding:14px 16px;box-shadow:0 2px 0 rgba(20,66,74,.07);min-width:0;}
.sfs-sim .sfs-card h3{font-size:1.05rem;margin:0 0 6px;font-weight:800;color:var(--sfs-ink);}
.sfs-sim .sfs-sub{font-size:.86rem;color:var(--sfs-soft);margin:0 0 8px;line-height:1.4;}
.sfs-sim .sfs-label{display:block;font-size:.8rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:var(--sfs-pink);margin:12px 0 4px;}
.sfs-sim .sfs-news{background:#e9f6f4;border:2px solid #a9d9d2;border-radius:14px;padding:10px 12px;margin-top:6px;}
.sfs-sim .sfs-newshead{display:flex;align-items:center;gap:8px;}
.sfs-sim .sfs-newshead .sfs-label{margin:0;}
.sfs-sim .sfs-avatar{font-size:24px;line-height:1;}
.sfs-sim .sfs-newstext{margin:6px 0 8px;font-size:.93rem;line-height:1.4;font-weight:600;color:var(--sfs-ink);}
.sfs-sim .sfs-optrow{display:grid;gap:6px;}
.sfs-sim .sfs-ansrow{grid-template-columns:1fr;}
.sfs-sim .sfs-opt{position:relative;display:flex;flex-direction:column;gap:2px;border:2px solid var(--sfs-line);background:#fffdf8;border-radius:12px;padding:8px 10px;font-size:.88rem;color:var(--sfs-ink);cursor:pointer;user-select:none;transition:border-color .12s,background .12s,transform .12s,box-shadow .12s;}
.sfs-sim .sfs-ansrow .sfs-opt{flex-direction:row;align-items:center;justify-content:space-between;gap:8px;background:#fff;}
.sfs-sim .sfs-opt:hover{border-color:#6fb7ad;}
.sfs-sim .sfs-opt input{position:absolute;opacity:0;width:1px;height:1px;margin:0;pointer-events:none;}
.sfs-sim .sfs-opt:focus-within{outline:3px solid #2a8c84;outline-offset:2px;}
.sfs-sim .sfs-opt.sfs-sel{border-color:var(--sfs-violet);background:#e4f4f1;box-shadow:0 3px 0 rgba(14,107,107,.25);transform:translateY(-1px);}
.sfs-sim .sfs-em{font-size:1.7rem;line-height:1.1;}
.sfs-sim .sfs-optname{font-weight:700;line-height:1.2;}
.sfs-sim .sfs-optnote{font-size:.76rem;color:var(--sfs-soft);line-height:1.25;}
.sfs-sim .sfs-tags{display:flex;gap:4px;flex-wrap:wrap;margin-top:2px;}
.sfs-sim .sfs-tag{display:inline-block;font-size:.76rem;font-weight:700;border-radius:999px;padding:1px 7px;background:#f1eee6;color:var(--sfs-ink);white-space:nowrap;}
.sfs-sim .sfs-tag.sfs-tpos{background:#e3f3e6;color:#1f5e2c;}
.sfs-sim .sfs-tag.sfs-tneg{background:#fbe3e1;color:#8e231e;}
.sfs-sim .sfs-preview{margin-top:10px;font-size:.86rem;background:#faf7ef;border:1px dashed var(--sfs-line);border-radius:10px;padding:8px 10px;line-height:1.45;}
.sfs-sim .sfs-preview b{font-size:.95rem;}
.sfs-sim .sfs-actions{display:flex;gap:8px;margin-top:12px;}
.sfs-sim .sfs-run{flex:1;background:var(--sfs-pink);color:#fff;border:0;border-radius:12px;padding:12px 14px;font-size:1.02rem;font-weight:800;cursor:pointer;box-shadow:0 3px 0 #7a2f10;}
.sfs-sim .sfs-run:hover{background:#9a3c14;}
.sfs-sim .sfs-run:focus-visible{outline:3px solid var(--sfs-violet);outline-offset:2px;}
.sfs-sim .sfs-done .sfs-controls{opacity:.55;pointer-events:none;}
.sfs-sim .sfs-hint{margin-top:10px;background:#fff6dc;border:2px solid #e2b54a;color:#4d3800;border-radius:12px;padding:9px 12px;font-size:.92rem;font-weight:600;line-height:1.4;}
.sfs-sim .sfs-board{display:flex;flex-direction:column;gap:6px;}
.sfs-sim .sfs-chartwrap{position:relative;height:200px;}
.sfs-sim .sfs-histwrap{overflow-x:auto;}
.sfs-sim .sfs-hist{width:100%;border-collapse:collapse;font-size:.84rem;}
.sfs-sim .sfs-hist th,.sfs-sim .sfs-hist td{padding:5px 6px;border-bottom:1px solid var(--sfs-line);text-align:left;white-space:nowrap;}
.sfs-sim .sfs-summary{display:none;margin-top:12px;}
.sfs-sim .sfs-summary.sfs-on{display:block;}
.sfs-sim .sfs-cm{background:#eef8f6;border:2px solid var(--sfs-violet);border-radius:14px;padding:14px 16px;}
.sfs-sim .sfs-cmtitle{margin:0 0 6px;font-size:1.2rem;color:var(--sfs-violet);}
.sfs-sim .sfs-cmscore{font-size:1.1rem;font-weight:800;}
.sfs-sim .sfs-cmstars{color:#b07a00;margin-left:8px;font-size:1.3rem;}
.sfs-sim .sfs-cmverdict{font-weight:700;margin:4px 0 10px;}
.sfs-sim .sfs-cmkpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px;margin-bottom:10px;}
.sfs-sim .sfs-cmkpi{background:#fff;border:1px solid var(--sfs-line);border-radius:10px;padding:8px;display:flex;flex-direction:column;}
.sfs-sim .sfs-cmkpi b{font-size:1.05rem;}
.sfs-sim .sfs-cmkpi span{font-size:.78rem;color:var(--sfs-soft);}
.sfs-sim .sfs-cm h4{margin:10px 0 4px;font-size:.95rem;}
.sfs-sim .sfs-cm ul,.sfs-sim .sfs-cm ol{margin:0;padding-left:20px;font-size:.88rem;line-height:1.45;}
.sfs-sim .sfs-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0;}
@media (max-width:860px){
 .sfs-sim{padding:12px;border-radius:0;}
 .sfs-sim .sfs-grid{grid-template-columns:1fr;}
 .sfs-sim .sfs-title h1{font-size:1.3rem;}
 .sfs-sim .sfs-brow{grid-template-columns:minmax(0,110px) 1fr auto;}
}
@media (max-width:400px){
 .sfs-sim .sfs-chip{font-size:.8rem;padding:5px 9px;}
 .sfs-sim .sfs-em{font-size:1.4rem;}
}

.sfs-sim .sfs-maintitle{font-size:.95rem;font-weight:700;margin:0 0 6px;color:var(--sfs-ink);}
.sfs-sim .sfs-mainrow{grid-template-columns:1fr 1fr;}
.sfs-sim .sfs-opt.sfs-off{opacity:.55;}
.sfs-sim .sfs-stage{position:relative;border-radius:14px;padding:12px;min-height:240px;background:linear-gradient(180deg,#bfe6f0 0%,#e8f6f2 55%,#d9c7a3 56%,#cdb88f 100%);overflow:hidden;color:var(--sfs-ink);}
.sfs-sim .sfs-stage.sfs-rain{background:linear-gradient(180deg,#8a9aa6 0%,#c3cdd3 55%,#a99b80 56%,#9c8e74 100%);}
.sfs-sim .sfs-awning{height:22px;border-radius:8px 8px 0 0;background:repeating-linear-gradient(90deg,#e04f1d 0 22px,#fff 22px 44px);box-shadow:0 3px 0 rgba(0,0,0,.12);}
.sfs-sim .sfs-booth{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:center;background:#fff;border:3px solid #8a5a2b;border-top:0;border-radius:0 0 10px 10px;padding:8px 10px;}
.sfs-sim .sfs-sign{background:#1f2a33;color:#fff;border-radius:8px;padding:6px 10px;text-align:center;min-width:88px;}
.sfs-sim .sfs-sign b{display:block;font-size:1.25rem;color:var(--sfs-gold);}
.sfs-sim .sfs-sign span{font-size:.72rem;}
.sfs-sim .sfs-shelf{font-size:1.2rem;line-height:1.25;letter-spacing:1px;word-break:break-all;min-height:28px;}
.sfs-sim .sfs-shelfnote{font-size:.76rem;color:var(--sfs-soft);}
.sfs-sim .sfs-crew{margin-top:6px;font-size:1.3rem;min-height:28px;}
.sfs-sim .sfs-queue{margin-top:10px;font-size:1.25rem;line-height:1.3;min-height:30px;word-break:break-all;}
.sfs-sim .sfs-left{opacity:.5;}
.sfs-sim .sfs-stagefoot{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;font-size:.84rem;margin-top:6px;font-weight:700;}
.sfs-sim .sfs-hours{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;}
.sfs-sim .sfs-hour{border:2px solid var(--sfs-line);border-radius:10px;padding:6px 4px;text-align:center;background:#fffdf8;min-width:0;}
.sfs-sim .sfs-hour.sfs-now{border-color:var(--sfs-gold);box-shadow:0 0 0 3px rgba(242,177,52,.35);}
.sfs-sim .sfs-hour.sfs-past{background:#f3efe6;}
.sfs-sim .sfs-hh{font-weight:800;font-size:.86rem;}
.sfs-sim .sfs-crowdtag{font-size:.72rem;color:var(--sfs-soft);line-height:1.2;min-height:2.4em;}
.sfs-sim .sfs-hcrew{font-size:1rem;min-height:1.4em;word-break:break-all;}
.sfs-sim .sfs-hsold{font-size:.72rem;font-weight:700;}
.sfs-sim .sfs-poolbar{grid-column:1/-1;font-size:.84rem;margin-top:4px;}
.sfs-sim .sfs-board{display:flex;flex-direction:column;gap:8px;}
.sfs-sim .sfs-eq{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:6px;align-items:center;background:#1f2a33;color:#fff;border-radius:12px;padding:10px;text-align:center;}
.sfs-sim .sfs-eq b{display:block;font-size:1.15rem;}
.sfs-sim .sfs-eq span{font-size:.72rem;color:#d5e3e6;}
.sfs-sim .sfs-eq .sfs-op{font-size:1.3rem;font-weight:800;}
.sfs-sim .sfs-eq .sfs-pos b{color:#9ee2a8;}
.sfs-sim .sfs-eq .sfs-neg b{color:#ff9d93;}
.sfs-sim .sfs-lines{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.sfs-sim .sfs-lines ul{margin:0;padding-left:16px;font-size:.84rem;line-height:1.45;}
.sfs-sim .sfs-lines h4{margin:0 0 2px;font-size:.84rem;}
.sfs-sim .sfs-bempty{font-size:.86rem;color:var(--sfs-soft);}
.sfs-sim .sfs-flash{animation:sfs-flash 1.6s ease-out 1;}
@keyframes sfs-flash{0%{background:#fff1cc;}100%{background:transparent;}}
@media (prefers-reduced-motion: reduce){.sfs-sim .sfs-flash{animation:none;}}
@media (max-width:860px){
 .sfs-sim .sfs-lines{grid-template-columns:1fr;}
 .sfs-sim .sfs-hours{gap:3px;}
 .sfs-sim .sfs-crowdtag{font-size:.66rem;}
}

