(function(){
'use strict';

/*===MODEL_START===*/
/* Pure fair-day model, no DOM. The build tests run it in Node. No randomness anywhere. Money in cents. */
var POOL = 9, HOURS = [24, 30, 64, 36, 18];
/* what the class sells: cost per unit, units one person serves in an hour, pull on the crowd, cents back per leftover */
var PRODUCTS = [
{id:'galletas', emoji:'🍪', cost:30, speed:25, pull:75,  salvage:0,  prices:[50, 100, 150, 200], dem:[150, 115, 85, 55]},
{id:'crepes',   emoji:'🥞', cost:90, speed:8,  pull:160, salvage:0,  prices:[100, 150, 200, 300], dem:[160, 125, 100, 60]},
{id:'limonada', emoji:'🍋', cost:50, speed:20, pull:100, salvage:0,  prices:[50, 100, 150, 200], dem:[150, 120, 100, 55]},
{id:'chapas',   emoji:'📛', cost:60, speed:10, pull:55,  salvage:30, prices:[100, 150, 200, 300], dem:[150, 115, 90, 55]}
];
var STOCKS = [60, 120, 180, 300];
var STAFF = [1, 2, 3, 4];
/* turns: the main pick and the news of the turn; the 12:00 news has two versions, decided by the stock bought */
var ROUNDS = [
{id:'producto', main:'product', news:'sitio',  v:['sitio']},
{id:'compra',   main:'stock',   news:'compra', v:['compra']},
{id:'precio',   main:'price',   news:'cartel', v:['cartel']},
{id:'h10',      main:'staff',   news:'floja',  v:['floja']},
{id:'h11',      main:'staff',   news:'rival',  v:['rival']},
{id:'h12',      main:'staff',   news:'hora',   v:['corto', 'cola'], dep:1},
{id:'h13',      main:'staff',   news:'lluvia', v:['lluvia']},
{id:'h14',      main:'staff',   news:'ultima', v:['ultima']}
];
var PITCH = [{fee:0, mult:70}, {fee:1000, mult:100}, {fee:2500, mult:130}];
var SIGN = [{fee:0, mult:85, free:0}, {fee:300, mult:100, free:0}, {fee:300, mult:115, free:15}];
var BUY = [{mult:100, fee:0, back:0}, {mult:70, fee:800, back:0}, {mult:120, fee:0, back:1}];
var RUSH_COST = 150, RAIN_TENT = 400, MEGA = 600;

function clampIdx(v, n){ v = parseInt(v, 10); return isNaN(v) ? -1 : Math.max(-1, Math.min(n - 1, v)); }
function variantOf(r, picks){
var R = ROUNDS[r];
if(R.dep === undefined) return R.v[0];
var p = picks[R.dep] ? clampIdx(picks[R.dep][0], 4) : -1;
return p >= 2 ? R.v[1] : R.v[0];
}
function ctxOf(picks){
var pk = function(r, k, m){ return picks[r] ? clampIdx(picks[r][k], m) : -1; };
var pi = pk(0, 0, 4), prod = PRODUCTS[Math.max(0, pi)], buy = BUY[Math.max(0, pk(1, 1, 3))];
return {has:pi >= 0, prod:prod, pitch:PITCH[Math.max(0, pk(0, 1, 3))], buy:buy, buyI:pk(1, 1, 3), stockI:pk(1, 0, 4),
sign:SIGN[Math.max(0, pk(2, 1, 3))], signI:pk(2, 1, 3), pitchI:pk(0, 1, 3), priceI:Math.max(0, pk(2, 0, 4)),
unit:Math.round(prod.cost * buy.mult / 100), cola:pk(1, 0, 4) >= 2};
}
function freshState(){ return {cost:0, rev:0, stock:0, bought:0, pool:POOL, price:0, keep:100, sold:0, lost:0, waste:0, back:0, extra:0, given:0,
cStock:0, cPitch:0, cFuel:0, cSign:0, cMega:0, cTent:0, cRush:0, iSales:0, cut:0, pool12:-1}; }
function copyState(s){ var o = {}; for(var k in s) o[k] = s[k]; return o; }

/* one turn applied to the state; m is the main pick, a the news answer (minus one = not chosen yet) */
function step(st, c, r, m, a){
var t = {r:r, id:ROUNDS[r].id, main:m, ans:a, v:r === 5 ? (c.cola ? 'cola' : 'corto') : ROUNDS[r].v[0], sold:0, demand:0, lost:0, staff:0, price:0};
var before = st.rev - st.cost;
if(r === 0){ if(a >= 0){ st.cost += c.pitch.fee; st.cPitch += c.pitch.fee; } }
else if(r === 1){
if(m >= 0 && c.has){ st.bought = STOCKS[m]; st.stock = st.bought; st.cost += st.bought * c.unit; st.cStock += st.bought * c.unit; }
if(a >= 0){ st.cost += c.buy.fee; st.cFuel += c.buy.fee; }
}
else if(r === 2){
st.price = Math.max(0, m);
if(a >= 0){ st.cost += c.sign.fee; st.cSign += c.sign.fee; var g = Math.min(st.stock, c.sign.free); st.stock -= g; st.given += g; t.given = g; }
}
else {
var h = r - 3, mult = 100, extraStaff = 0, pmult = 100, closed = false, tray = 0;
var want = m >= 0 ? STAFF[m] : 0;
if(r === 3){
if(a === 0){ st.price = Math.max(0, st.price - 1); st.cut++; }
if(a === 2) tray = 1;
} else if(r === 4){
if(a === 0){ st.price = Math.max(0, st.price - 1); st.cut++; }
if(a === 1) st.keep = 90;
if(a === 2){ st.cost += MEGA; st.cMega += MEGA; }
} else if(r === 5){
st.pool12 = st.pool;
if(!c.cola){
if(a === 1 && c.has){ st.stock += 40; st.bought += 40; st.extra += 40; var rc = 40 * Math.round(c.prod.cost * RUSH_COST / 100); st.cost += rc; st.cRush += rc; extraStaff = -1; }
if(a === 2) st.price = Math.min(3, st.price + 1);
} else {
if(a === 1) st.price = Math.min(3, st.price + 1);
if(a === 2) extraStaff = 1;
}
} else if(r === 6){
if(a === 0) closed = true;
if(a === 1){ mult = 80; st.cost += RAIN_TENT; st.cTent += RAIN_TENT; }
if(a === 2){ mult = 45; var d = Math.min(st.stock, 10); st.stock -= d; st.waste += d; t.ruined = d; }
} else if(r === 7){
if(a === 1){ pmult = 50; mult = 220; }
if(a === 2){ pmult = 75; mult = 150; }
}
var staff = 0;
if(!closed){
var take = Math.min(want + tray, st.pool);
st.pool -= take;
if(tray && take > want) mult = 140;
staff = Math.max(0, Math.min(take, want) + extraStaff);
}
var price = Math.round(c.prod.prices[st.price] * pmult / 100);
var demand = closed || !c.has ? 0 : Math.round(HOURS[h] * c.pitch.mult / 100 * c.sign.mult / 100 * c.prod.pull / 100 * c.prod.dem[st.price] / 100 * st.keep / 100 * mult / 100);
var sold = Math.min(demand, staff * c.prod.speed, st.stock);
st.stock -= sold; st.sold += sold; st.lost += demand - sold; st.rev += sold * price; st.iSales += sold * price;
t.staff = staff; t.price = price; t.demand = demand; t.sold = sold; t.lost = demand - sold; t.closed = closed;
if(r === 7 && m >= 0){
t.left = st.stock;
var back = c.buy.back ? st.stock * c.unit : st.stock * c.prod.salvage;
st.back = back; st.rev += back;
if(!c.buy.back && !c.prod.salvage) st.waste += st.stock;
}
}
t.money = (st.rev - st.cost) - before;
t.profit = st.rev - st.cost; t.stock = st.stock; t.pool = st.pool; t.rev = st.rev; t.cost = st.cost;
return t;
}

/* one whole run: picks is a list of [main option, news answer] per turn, 0 based */
function runAll(picks){
var n = Math.min(picks.length, ROUNDS.length), c = ctxOf(picks), st = freshState(), turns = [];
for(var r = 0; r < n; r++){
turns.push(step(st, c, r, clampIdx(picks[r][0], 4), clampIdx(picks[r][1], 3)));
}
return {turns:turns, rev:st.rev, cost:st.cost, profit:st.rev - st.cost, sold:st.sold, lost:st.lost, waste:st.waste, given:st.given,
back:st.back, stock:st.stock, pool:st.pool, bought:st.bought, extra:st.extra, unit:c.unit, price:st.price, prod:c.has ? c.prod.id : '',
cStock:st.cStock, cPitch:st.cPitch, cFuel:st.cFuel, cSign:st.cSign, cMega:st.cMega, cTent:st.cTent, cRush:st.cRush, iSales:st.iSales,
cut:st.cut, pool12:st.pool12, ctx:c};
}

/* yardstick: the best profit any plan can reach, found by an exhaustive search when the model was tuned (test.js re-checks it) */
var BEST_PROFIT = 18100;
function scoreOf(r){
if(!r.turns.length) return 0;
return Math.max(0, Math.min(100, Math.round(100 * r.profit / BEST_PROFIT)));
}

var MODEL = {POOL:POOL, HOURS:HOURS, PRODUCTS:PRODUCTS, STOCKS:STOCKS, STAFF:STAFF, ROUNDS:ROUNDS, PITCH:PITCH, SIGN:SIGN, BUY:BUY,
RUSH_COST:RUSH_COST, RAIN_TENT:RAIN_TENT, MEGA:MEGA, BEST_PROFIT:BEST_PROFIT, clampIdx:clampIdx, variantOf:variantOf,
ctxOf:ctxOf, freshState:freshState, copyState:copyState, step:step, runAll:runAll, scoreOf:scoreOf};
if(typeof module !== 'undefined' && module.exports){ module.exports = MODEL; }
/*===MODEL_END===*/
/* ---------------- screen and USF adapter ---------------- */
function t(k, vars){ return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k, vars) : k; }
function el(id){ return document.getElementById(id); }
function esc(s){ return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\x22/g, '&quot;'); }
function setText(id, v){ var n = el(id); if(n) n.textContent = String(v); }
function groupDigits(s, sep){ return s.replace(/\B(?=(\d{3})+(?!\d))/g, sep); }
/* cents to text: whole euros print without decimals */
function eur(c){
var v = Math.round(c), neg = v < 0, a = Math.abs(v), e = Math.floor(a / 100), d = a % 100;
var s = groupDigits(String(e), t('thou_sep')) + (d ? t('dec_sep') + (d < 10 ? '0' : '') + d : '');
return (neg ? '−' : '') + s + ' €';
}
function signed(c){ return (c > 0 ? '+' : '') + eur(c); }

var NR = MODEL.ROUNDS.length;
var HOUR_LABELS = ['10:00', '11:00', '12:00', '13:00', '14:00'];
function rowsOf(G){ return (G && G.turns) || []; }
function picksOf(rows){ return rows.map(function(r){ return [r[0], r[1]]; }); }
function starsOf(score){ return score >= 80 ? '★★★' : (score >= 55 ? '★★☆' : '★☆☆'); }
function tierOf(score){ return score >= 80 ? 'top' : (score >= 55 ? 'good' : (score >= 30 ? 'meh' : 'flop')); }
function checkedVal(name){ var n = document.querySelector('input[name=' + name + ']:checked'); return n ? parseInt(n.value, 10) : -1; }
function readControls(){ return {ans: checkedVal('sfsAns'), opt: checkedVal('sfsOpt')}; }
function unitWord(run){ return t('u_' + (run.prod || 'none')); }

function tagsHtml(list){
return '<span class="sfs-tags">' + list.map(function(x){
return '<span class="sfs-tag ' + (x[1] || '') + '">' + esc(x[0]) + '</span>';
}).join('') + '</span>';
}
/* native radios inside each card: keyboard, screen readers and test bots can all use them */
function optHtml(name, idx, inner, extra){
var id = name + '_' + idx;
return '<label class="sfs-opt' + (extra || '') + '" for="' + id + '"><input type="radio" name="' + name + '" id="' + id + '" value="' + idx + '">' + inner + '</label>';
}
function feeTag(c){ return c ? [t('tag_pay', {x: eur(c)}), 'sfs-tneg'] : [t('tag_free'), '']; }

/* the answers of the news of turn r: label and the money the answer costs for sure (effects are not shown) */
function answerTags(r, v, i, ctx){
if(r === 0) return [feeTag(MODEL.PITCH[i].fee)];
if(r === 1) return [i === 1 ? feeTag(MODEL.BUY[1].fee) : [t('tag_unit', {x: eur(Math.round(ctx.prod.cost * MODEL.BUY[i].mult / 100))}), '']];
if(r === 2) return [feeTag(MODEL.SIGN[i].fee)];
if(r === 4 && i === 2) return [feeTag(MODEL.MEGA)];
if(r === 5 && v === 'corto' && i === 1) return [feeTag(40 * Math.round(ctx.prod.cost * MODEL.RUSH_COST / 100))];
if(r === 6 && i === 1) return [feeTag(MODEL.RAIN_TENT)];
return [];
}
function mainHtml(r, run, ctx, pool){
var R = MODEL.ROUNDS[r];
if(R.main === 'product') return MODEL.PRODUCTS.map(function(p, i){
return optHtml('sfsOpt', i, '<span class="sfs-em" aria-hidden="true">' + p.emoji + '</span><span class="sfs-optname">' + esc(t('p_' + p.id)) + '</span>' +
'<span class="sfs-optnote">' + esc(t('pn_' + p.id)) + '</span>' + tagsHtml([[t('tag_cost', {x: eur(p.cost)}), ''], [t('tag_speed', {n: p.speed}), '']]));
}).join('');
if(R.main === 'stock'){
var a = readControls().ans, unit = Math.round(ctx.prod.cost * MODEL.BUY[Math.max(0, a)].mult / 100);
return MODEL.STOCKS.map(function(n, i){
return optHtml('sfsOpt', i, '<span class="sfs-em" aria-hidden="true">📦</span><span class="sfs-optname">' + esc(n + ' ' + unitWord(run)) + '</span>' +
'<span class="sfs-tags"><span class="sfs-tag sfs-tneg" id="sfsOptTag_' + i + '">' + esc(t('tag_pay', {x: eur(n * unit)})) + '</span></span>');
}).join('');
}
if(R.main === 'price') return ctx.prod.prices.map(function(p, i){
var m = p - run.unit;
return optHtml('sfsOpt', i, '<span class="sfs-em" aria-hidden="true">🏷</span><span class="sfs-optname">' + esc(eur(p)) + '</span>' +
'<span class="sfs-optnote">' + esc(t('pr_note', {x: eur(run.unit)})) + '</span>' + tagsHtml([[t('tag_margin', {x: signed(m)}), m > 0 ? 'sfs-tpos' : 'sfs-tneg']]));
}).join('');
return MODEL.STAFF.map(function(n, i){
var short = n > pool;
return optHtml('sfsOpt', i, '<span class="sfs-em" aria-hidden="true">' + new Array(n + 1).join('🙋') + '</span><span class="sfs-optname">' + esc(t('st_' + n)) + '</span>' +
'<span class="sfs-optnote">' + esc(short ? t('st_short', {n: pool}) : t('st_note', {x: n * ctx.prod.speed, u: unitWord(run)})) + '</span>', short ? ' sfs-off' : '');
}).join('');
}

function buildChips(){
var G = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
var rows = rowsOf(G), r = rows.length;
var keep = readControls();
if(r >= NR) return;
var picks = picksOf(rows).concat([[-1, -1]]), run = MODEL.runAll(picks), ctx = run.ctx;
var v = MODEL.variantOf(r, picks);
setText('sfsNewsText', t('ev_' + v, {stock: run.stock, u: unitWord(run), pool: run.pool}));
var a = el('sfsAnswers');
if(a) a.innerHTML = [0, 1, 2].map(function(i){
return optHtml('sfsAns', i, '<span class="sfs-optname">' + esc(t('a_' + v + '_' + i)) + '</span>' + tagsHtml(answerTags(r, v, i, ctx)));
}).join('');
setText('sfsMainTitle', t('mt_' + MODEL.ROUNDS[r].main));
var o = el('sfsOptions');
if(o) o.innerHTML = mainHtml(r, run, ctx, run.pool);
setText('sfsTurnTitle', t('tt_' + MODEL.ROUNDS[r].id, {n: r + 1, left: NR - r}));
checkIdx(keep.ans, keep.opt);
}
/* the stock cards show the price of the shop picked in the news: only their price tags are rewritten, the radios stay */
function redrawMain(){
var G = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
var rows = rowsOf(G), r = rows.length;
if(r >= NR || MODEL.ROUNDS[r].main !== 'stock') return;
var a = readControls().ans, run = MODEL.runAll(picksOf(rows).concat([[-1, -1]]));
var unit = Math.round(run.ctx.prod.cost * MODEL.BUY[Math.max(0, a)].mult / 100);
MODEL.STOCKS.forEach(function(n, i){ var tag = el('sfsOptTag_' + i); if(tag) tag.textContent = t('tag_pay', {x: eur(n * unit)}); });
}
function checkIdx(ai, oi){
var a = ai >= 0 ? el('sfsAns_' + ai) : null, o = oi >= 0 ? el('sfsOpt_' + oi) : null;
if(a) a.checked = true; if(o) o.checked = true;
syncChips();
}
function syncChips(){
document.querySelectorAll('.sfs-opt').forEach(function(lab){
var inp = lab.querySelector('input');
if(inp) lab.classList.toggle('sfs-sel', !!inp.checked);
});
}
function clearChips(){
document.querySelectorAll('input[type=radio]').forEach(function(n){ var nm = n.getAttribute('name'); if(nm === 'sfsAns' || nm === 'sfsOpt') n.checked = false; });
syncChips();
}

var view = { seen: -1 };

function icons(ch, n, cap){ var s = ''; for(var i = 0; i < Math.min(n, cap); i++) s += ch; return s; }
/* the stall: price sign, stock on the shelf (one icon per 10 units), the crew of the hour, the queue served and lost */
function paintStage(run, focus){
var box = el('sfsStage'); if(!box) return;
var ctx = run.ctx, last = null;
for(var i = run.turns.length - 1; i >= 0; i--){ if(run.turns[i].r >= 3){ last = run.turns[i]; break; } }
if(focus && focus.r >= 3) last = focus;
box.className = 'sfs-stage' + (last && last.r === 6 && last.ans === 2 ? ' sfs-rain' : '');
var price = last ? last.price : (run.turns.length > 2 && run.turns[2].main >= 0 ? ctx.prod.prices[run.price] : 0);
var em = run.prod ? ctx.prod.emoji : '❔';
var shelf = run.stock > 0 ? icons(em, Math.ceil(run.stock / 10), 26) : '';
var crew = last ? (last.staff ? icons('🙋', last.staff, 6) : '💤') : '';
var q = last ? icons('🙂', Math.ceil(last.sold / 5), 20) + '<span class="sfs-left">' + icons('😞', Math.ceil(last.lost / 5), 20) + '</span>' : '';
box.innerHTML = '<div class="sfs-awning" aria-hidden="true"></div><div class="sfs-booth"><div class="sfs-sign"><span>' + esc(run.prod ? t('p_' + run.prod) : t('stage_noprod')) + '</span><b>' +
esc(price ? eur(price) : '–') + '</b></div><div><div class="sfs-shelf" aria-hidden="true">' + shelf + '</div><div class="sfs-shelfnote">' +
esc(t('stage_shelf', {n: run.stock, u: unitWord(run)})) + '</div><div class="sfs-crew" aria-hidden="true">' + crew + '</div></div></div>' +
'<div class="sfs-queue" aria-hidden="true">' + q + '</div>' +
'<div class="sfs-stagefoot"><span>' + esc(last ? t('stage_hour', {h: HOUR_LABELS[last.r - 3], s: last.sold, l: last.lost}) : t('stage_closed')) + '</span><span>' +
esc(t('stage_profit', {x: eur(run.profit)})) + '</span></div>';
setText('sfsStageAlt', t('stage_alt', {n: run.stock, u: unitWord(run), s: last ? last.sold : 0, l: last ? last.lost : 0, x: eur(run.profit)}));
}

/* who works when: five hours, the crowd expected, the volunteers placed and what each hour sold */
function paintHours(run, r){
var box = el('sfsHours'); if(!box) return;
var html = HOUR_LABELS.map(function(h, k){
var tr = run.turns[k + 3], cls = 'sfs-hour' + (k + 3 === r ? ' sfs-now' : (tr && k + 3 < r ? ' sfs-past' : ''));
var crew = tr ? (tr.closed ? '🌧' : (tr.staff ? icons('🙋', tr.staff, 6) : '—')) : '';
var sold = tr && (k + 3 < r || k + 3 === r) && tr.demand ? t('hr_sold', {s: tr.sold, l: tr.lost}) : '';
return '<div class="' + cls + '"><div class="sfs-hh">' + h + '</div><div class="sfs-crowdtag">' + esc(t('crowd_' + k)) + '</div><div class="sfs-hcrew" aria-hidden="true">' + crew + '</div><div class="sfs-hsold">' + esc(sold) + '</div></div>';
}).join('');
box.innerHTML = html + '<div class="sfs-poolbar">' + esc(t('pool_left', {n: run.pool, m: MODEL.POOL})) + '</div>';
}

/* the chalkboard: income minus costs equals profit, with every line so far */
function paintBoard(run){
var box = el('sfsBoard'); if(!box) return;
if(!run.turns.length){ box.innerHTML = '<p class="sfs-bempty">' + esc(t('board_empty')) + '</p>'; return; }
var inc = [['b_sales', run.iSales], ['b_back', run.back]].filter(function(x){ return x[1]; });
var cost = [['b_stock', run.cStock], ['b_pitch', run.cPitch], ['b_fuel', run.cFuel], ['b_sign', run.cSign], ['b_mega', run.cMega], ['b_rush', run.cRush], ['b_tent', run.cTent]].filter(function(x){ return x[1]; });
var li = function(list){ return list.length ? list.map(function(x){ return '<li>' + esc(t(x[0])) + ': ' + esc(eur(x[1])) + '</li>'; }).join('') : '<li>–</li>'; };
box.innerHTML = '<div class="sfs-eq"><div class="sfs-pos"><b>' + esc(eur(run.rev)) + '</b><span>' + esc(t('eq_inc')) + '</span></div><div class="sfs-op">−</div>' +
'<div class="sfs-neg"><b>' + esc(eur(run.cost)) + '</b><span>' + esc(t('eq_cost')) + '</span></div><div class="sfs-op">=</div>' +
'<div class="' + (run.profit >= 0 ? 'sfs-pos' : 'sfs-neg') + '"><b>' + esc(eur(run.profit)) + '</b><span>' + esc(t('eq_profit')) + '</span></div></div>' +
'<div class="sfs-lines"><div><h4>' + esc(t('eq_inc')) + '</h4><ul>' + li(inc) + '</ul></div><div><h4>' + esc(t('eq_cost')) + '</h4><ul>' + li(cost) + '</ul></div></div>' +
(run.waste ? '<p class="sfs-sub">' + esc(t('board_waste', {n: run.waste, u: unitWord(run)})) + '</p>' : '');
}

function setHint(key, vars){
var hint = el('sfsHint'); if(!hint) return;
hint.setAttribute('data-i18n', key);
hint.textContent = t(key, vars);
}
function paintPreview(now, r, c){
var box = el('sfsPreview'); if(!box) return;
var tr = now.turns[r];
if(!tr || (c.ans < 0 && c.opt < 0)){ box.textContent = t('preview_pick'); return; }
var line = t('preview_turn', {money: signed(tr.money), x: eur(now.profit)});
if(r >= 3 && c.opt >= 0) line += ' ' + t('preview_sell', {s: tr.sold, l: tr.lost, u: unitWord(now)});
box.textContent = line;
}
function hintAfter(run){
var tr = run.turns[run.turns.length - 1], r = tr.r;
if(r === 0) return ['hint_after0', {}];
if(r === 1) return ['hint_after1', {n: run.stock, u: unitWord(run), x: eur(run.cost)}];
if(r === 2) return ['hint_after2', {m: signed(run.ctx.prod.prices[run.price] - run.unit)}];
if(tr.closed) return ['hint_closed', {}];
if(tr.lost > 0 && run.stock === 0) return ['hint_nostock', {n: tr.lost}];
if(tr.lost > 0) return ['hint_lost', {n: tr.lost}];
if(run.pool <= 1 && r < 7) return ['hint_pool', {n: run.pool}];
return ['hint_ok', {s: tr.sold, x: eur(run.profit)}];
}

/* the whole screen is drawn from the saved state, so a reload shows exactly what was there */
function refresh(){
var sim = window.mySimulation; if(!sim || !sim.state) return;
var state = sim.state, G = state.domainState || {};
var rows = rowsOf(G), r = rows.length, finished = r >= NR;
if(r !== view.seen){ view.seen = r; clearChips(); buildChips(); }
var done = MODEL.runAll(picksOf(rows));
var c = finished ? {ans: -1, opt: -1} : readControls();
var now = finished ? done : MODEL.runAll(picksOf(rows).concat([[c.opt, c.ans]]));
setText('sfsProfit', eur(now.profit));
var chip = el('sfsProfitChip'); if(chip) chip.classList.toggle('sfs-neg', now.profit < 0);
setText('sfsStock', now.stock);
setText('sfsPool', now.pool);
var root = el('sfsRoot'); if(root) root.classList.toggle('sfs-done', finished);
paintStage(now, !finished && (c.opt >= 0 || c.ans >= 0) ? now.turns[r] : null);
paintHours(now, finished ? NR : r);
paintBoard(now);
if(!finished) paintPreview(now, r, c); else setText('sfsPreview', '');
if(finished) setHint('hint_done');
else if(c.ans >= 0 || c.opt >= 0) setHint('hint_plan');
else if(r === 0) setHint('hint_start');
else { var h = hintAfter(done); setHint(h[0], h[1]); }
var alt = el('sfsChartAlt');
if(alt) alt.textContent = done.turns.length ? t('chart_alt') + ' ' + done.turns.map(function(x){ return (x.r + 1) + ': ' + eur(x.profit); }).join(', ') + '.' : t('chart_alt_none');
var box = el('sfsSummary');
if(box){
if(finished && sim.adapter){
box.innerHTML = sim.adapter.formatCompletionMessage(sim.adapter.getPerformanceSummary(state.history || []));
box.classList.add('sfs-on');
} else { box.innerHTML = ''; box.classList.remove('sfs-on'); }
}
}

function onAnswer(){ syncChips(); redrawMain(); refresh(); }
function onControlChange(){ syncChips(); refresh(); }
function wireControls(){
var a = el('sfsAnswers'); if(a) a.addEventListener('change', onAnswer);
var o = el('sfsOptions'); if(o) o.addEventListener('change', onControlChange);
}

class FairStallAdapter extends USF.SimulationAdapter {
constructor(){ super(); this.name = 'El puesto de la feria'; this.version = '1.0.0'; }

initialize(state){
if(!state.domainState || !state.domainState.turns){
state.domainState = { turns: [], performance: {overallScore: 0, tier: 'flop'} };
}
if(!state.decisions || state.decisions.opt === undefined){
state.decisions = {opt: -1, ans: -1, forPeriod: 0};
}
}

validateDecisions(decisions){
var c = readControls();
var missing = [];
if(c.ans < 0) missing.push(t('lab_news'));
if(c.opt < 0) missing.push(t('lab_main'));
if(missing.length){
if(window.mySimulation) window.mySimulation.uiManager.showNotification(t('need_choice', {rows: missing.join(' + ')}), 'warning');
return false;
}
decisions.opt = c.opt; decisions.ans = c.ans;
decisions.forPeriod = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.currentPeriod : 0;
return true;
}

calculateResults(state){
var o = this._runTurn(state);
return { opt: o.opt, ans: o.ans, sold: o.sold, money: o.money, profit: o.profit, overallScore: o.score };
}

/* one turn, computed only from the rows of the turns before it and from the two choices of this turn */
_runTurn(state){
var G = state.domainState, d = state.decisions || {};
var turn = Math.max(1, Math.min(NR, parseInt(state.currentPeriod, 10) || 1));
var idx = turn - 1;
var rows = rowsOf(G).slice(0, idx);
var li = MODEL.clampIdx(d.opt, 4), ri = MODEL.clampIdx(d.ans, 3);
rows[idx] = [Math.max(0, li), Math.max(0, ri)];
G.turns = rows;
var run = MODEL.runAll(picksOf(rows)), tr = run.turns[idx];
var score = this._composite(G);
G.performance = { overallScore: score, tier: tierOf(score) };
G.performanceTier = tierOf(score);
return { opt: MODEL.ROUNDS[idx].main + rows[idx][0], ans: tr.v + rows[idx][1], sold: tr.sold, money: tr.money, profit: run.profit, score: score };
}

/* one formula for the grade, used by every save and by the final summary */
_composite(ds){
var rows = rowsOf(ds);
if(!rows.length) return 0;
return MODEL.scoreOf(MODEL.runAll(picksOf(rows)));
}

/* cards start empty every turn; a choice is put back only for a turn not yet played */
_syncControlsFromDecisions(d){
var sim = window.mySimulation;
if(d && sim && sim.state && d.forPeriod && d.forPeriod === sim.state.currentPeriod && (sim.state.history || []).length < d.forPeriod){
checkIdx(MODEL.clampIdx(d.ans, 3), MODEL.clampIdx(d.opt, 4));
} else syncChips();
}

setupUI(uiManager){
uiManager.bind('currentDay', 'currentPeriod');
uiManager.bind('maxPeriods', 'maxPeriods');
wireControls();
var self = this;
var sim = window.mySimulation;
var repaint = function(){
try { buildChips(); refresh(); } catch(e) { syncChips(); }
};
var reload = function(){
try { view.seen = -1; refresh(); } catch(e) { syncChips(); }
};
document.addEventListener('express:langchanged', repaint);
try {
if(sim && sim.eventBus){
sim.eventBus.on('language:changed', repaint);
sim.eventBus.on('period:undone', reload);
sim.eventBus.on('state:loaded', function(){ reload(); self._syncControlsFromDecisions(sim.state.decisions); refresh(); });
}
} catch(e) { syncChips(); }
setTimeout(reload, 0);
}

getChartConfig(){
return { sfsProfitChart: {
type: 'bar',
data: { labels: [], datasets: [{ label: t('ds_profit'), data: [], backgroundColor: [], borderRadius: 6 }] },
options: { responsive: true, maintainAspectRatio: false,
plugins: { legend: {display: false}, title: {display: false} },
scales: { y: {ticks: {precision: 0}} } }
}};
}

getChartData(state){
var G = (state && state.domainState) || {};
var hist = MODEL.runAll(picksOf(rowsOf(G))).turns.map(function(x){ return Math.round(x.profit) / 100; });
refresh();
return { sfsProfitChart: {
labels: hist.map(function(p, i){ return t('turn_short') + (i + 1); }),
datasets: [{ label: t('ds_profit'), data: hist.slice(), backgroundColor: hist.map(function(p){ return p >= 0 ? '#2f7d3f' : '#c8372d'; }) }]
}};
}

getHistoryTableConfig(){
var oLab = function(v){ var m = String(v || '').match(/^([a-z]+)(\d)$/); return m ? t('h_' + m[1] + '_' + m[2]) : String(v); };
var aLab = function(v){ var m = String(v || '').match(/^([a-z]+)(\d)$/); return m ? t('a_' + m[1] + '_' + m[2]) : String(v); };
return [
{key: 'results.opt',    label: 'Decision', i18nKey: 'col_opt',    formatter: oLab},
{key: 'results.ans',    label: 'News',     i18nKey: 'col_ans',    formatter: aLab},
{key: 'results.sold',   label: 'Sold',     i18nKey: 'col_sold',   formatter: function(v){ return String(v); }},
{key: 'results.money',  label: 'Money',    i18nKey: 'col_money',  formatter: signed},
{key: 'results.profit', label: 'Profit',   i18nKey: 'col_profit', formatter: eur}
];
}

/* everything the debrief says is read from the rows of this run */
getPerformanceSummary(history){
var sim = window.mySimulation;
var G = (sim && sim.state && sim.state.domainState) || {};
var rows = rowsOf(G);
var hist = history || [];
if(!rows.length) return {};
var run = MODEL.runAll(picksOf(rows));
var score = this._composite(G);
var tier = tierOf(score);
var rush = run.turns[5] || {};
return {
composite: score, overallScore: score, totalScore: score, score: score,
performance: tier, performanceKey: tier, performanceLabel: t('grade_' + tier), stars: starsOf(score),
totalPeriods: rows.length, savedPeriods: hist.length, finished: rows.length >= NR,
profit: run.profit, rev: run.rev, cost: run.cost, sold: run.sold, lost: run.lost, waste: run.waste, prod: run.prod, unitWord: unitWord(run),
slow: !!run.prod && run.ctx.prod.speed <= 10 && run.lost >= 40, early: rows.length > 5 && run.pool12 >= 0 && run.pool12 <= 2,
rushLost: rush.lost || 0, cut: run.cut, cheap: rows.length > 2 && run.price === 0, back: run.back, stock: run.stock
};
}

formatCompletionMessage(summary){
var s = summary || {};
if(s.overallScore == null) return '<div class="sfs-cm"><p>' + esc(t('done_title')) + '</p></div>';
var kpi = function(lab, val){ return '<div class="sfs-cmkpi"><b>' + esc(val) + '</b><span>' + esc(t(lab)) + '</span></div>'; };
var ins = [];
if(s.profit < 0) ins.push(t('ins_loss', {x: eur(-s.profit)}));
if(s.slow) ins.push(t('ins_popular', {p: t('p_' + s.prod), n: s.lost}));
if(s.early) ins.push(t('ins_early', {n: s.rushLost}));
if(s.cut) ins.push(t('ins_cut'));
if(s.cheap) ins.push(t('ins_cheap'));
if(s.waste >= 20) ins.push(t('ins_waste', {n: s.waste, u: s.unitWord}));
if(s.back) ins.push(t('ins_back', {x: eur(s.back)}));
if(!s.slow && !s.early && s.lost >= 25) ins.push(t('ins_lost', {n: s.lost}));
if(!ins.length) ins.push(t('ins_fine'));
var learn = ['cm_learn_1', 'cm_learn_2', 'cm_learn_3', 'cm_learn_4'].map(function(k){ return '<li>' + esc(t(k)) + '</li>'; }).join('');
return '<div class="sfs-cm">' +
'<h3 class="sfs-cmtitle">' + esc(t('done_title')) + '</h3>' +
'<div class="sfs-cmscore">' + esc(t('cm_score', {score: s.overallScore})) + '<span class="sfs-cmstars" aria-hidden="true">' + s.stars + '</span></div>' +
'<p class="sfs-cmverdict">' + esc(s.performanceLabel) + '</p>' +
'<div class="sfs-cmkpis">' + kpi('cm_kpi_profit', eur(s.profit)) + kpi('cm_kpi_sold', String(s.sold)) +
kpi('cm_kpi_lost', String(s.lost)) + kpi('cm_kpi_waste', String(s.waste)) + '</div>' +
'<h4>' + esc(t('cm_learn_h')) + '</h4><ul>' + learn + '</ul>' +
'<h4>' + esc(t('cm_ins_h')) + '</h4><ul>' + ins.slice(0, 5).map(function(x){ return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>' +
'<p class="sfs-sub">' + esc(t('cm_ins_note')) + '</p>' +
'<h4>' + esc(t('cm_q_h')) + '</h4><ol>' + ['cm_q1', 'cm_q2', 'cm_q3'].map(function(k){ return '<li>' + esc(t(k)) + '</li>'; }).join('') + '</ol>' +
'</div>';
}

